require __DIR__.'/../bootstrap.php';require_login();$u=current_user();analytics_require_premium($u);$site=analytics_owned_site((int)$u['id']);
if(!$site){$site=analytics_create_site((int)$u['id'],'My Website','');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{
    $action=(string)($_POST['action']??'');
    if($action==='site'){db()->prepare('UPDATE analytics_sites SET name=?,domain=?,enabled=?,consent_required=?,anonymize_ip=?,retention_days=?,updated_at=NOW() WHERE id=? AND owner_user_id=?')->execute([trim((string)$_POST['name']),trim((string)$_POST['domain']),isset($_POST['enabled'])?1:0,isset($_POST['consent_required'])?1:0,isset($_POST['anonymize_ip'])?1:0,max(30,min(3650,(int)$_POST['retention_days'])) ,(int)$site['id'],(int)$u['id']]);flash('success','Analytics tracking settings saved.');}
    elseif($action==='goal'){ $gn=trim((string)$_POST['goal_name']);$ge=preg_replace('/[^a-zA-Z0-9_.:-]/','',trim((string)$_POST['event_name']));if($gn!==''&&$ge!=='')db()->prepare('INSERT INTO analytics_goals(site_id,name,event_name,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([(int)$site['id'],$gn,$ge]);flash('success','Conversion goal added.');}
}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/analytics/');}
$range=(string)($_GET['range']??'7d');try{$r=analytics_report((int)$site['id'],$range);}catch(Throwable $e){$r=['site'=>$site,'pageviews'=>0,'sessions'=>0,'visitors'=>0,'bounces'=>0,'bounceRate'=>0,'realtime'=>0,'agg'=>['AVG(engagement_seconds)'=>0,'AVG(pageviews)'=>0,'SUM(converted)'=>0],'conversions'=>0,'pages'=>[],'sources'=>[],'devices'=>[],'countries'=>[],'browsers'=>[],'events'=>[],'trend'=>[],'hours'=>[]];}
